-- HRP Synapse · 0018 GST billing: tax invoices and credit notes (FY-wise numbering, place of supply,
-- CGST/SGST vs IGST), payments with allocations, receivables. Exports (e-invoice JSON, GSTR-1, Tally)
-- are generated by the API from these tables.

create table invoices (
  id                 uuid primary key default app.uuidv7(),
  tenant_id          uuid not null default app.current_tenant_id() references tenants (id) on delete cascade,
  name               text not null,
  doc_type           text not null default 'tax_invoice' check (doc_type in ('tax_invoice', 'credit_note', 'proforma')),
  invoice_number     text,
  status             text not null default 'draft' check (status in ('draft', 'issued', 'partially_paid', 'paid', 'cancelled')),
  approval_status    text not null default 'not_required' check (approval_status in ('not_required', 'required', 'pending', 'approved', 'rejected')),
  invoice_date       date not null default current_date,
  due_date           date,
  financial_year     text,
  account_id         uuid,
  contact_id         uuid,
  sales_order_id     uuid,
  milestone_id       uuid,
  original_invoice_id uuid,
  -- buyer / seller snapshots taken at issue (later edits to the account don't change a filed invoice)
  buyer_name         text,
  buyer_gstin        text check (buyer_gstin is null or buyer_gstin ~ '^[0-9]{2}[A-Z0-9]{13}$'),
  buyer_address      text,
  buyer_state        text,
  buyer_pincode      text,
  shipping_address   text,
  place_of_supply    text,
  pos_code           text check (pos_code is null or pos_code ~ '^[0-9]{2}$'),
  seller_gstin       text,
  seller_state       text,
  supply_type        text check (supply_type in ('intra', 'inter', 'export')),
  reverse_charge     boolean not null default false,
  currency           char(3) not null default 'INR',
  subtotal           numeric(18, 2) not null default 0,
  discount_total     numeric(18, 2) not null default 0,
  taxable_total      numeric(18, 2) not null default 0,
  cgst_total         numeric(18, 2) not null default 0,
  sgst_total         numeric(18, 2) not null default 0,
  igst_total         numeric(18, 2) not null default 0,
  tax_total          numeric(18, 2) not null default 0,
  round_off          numeric(8, 2) not null default 0,
  grand_total        numeric(18, 2) not null default 0,
  max_discount_pct   numeric(5, 2) not null default 0,
  amount_paid        numeric(18, 2) not null default 0,
  amount_credited    numeric(18, 2) not null default 0,
  balance_due        numeric(18, 2) generated always as (grand_total - amount_paid - amount_credited) stored,
  -- e-invoice registration (IRP) details once registered
  irn                text check (length(irn) <= 64),
  ack_no             text check (length(ack_no) <= 30),
  ack_date           timestamptz,
  notes              text,
  terms              text,
  issued_at          timestamptz,
  cancelled_at       timestamptz,
  cancel_reason      text,
  overdue_notified_at timestamptz,
  owner_id           uuid,
  custom             jsonb not null default '{}'::jsonb,
  created_by         uuid default app.current_user_id(),
  updated_by         uuid,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  deleted_at         timestamptz,
  merged_into        uuid,
  version            integer not null default 1,
  unique (tenant_id, id),
  check (doc_type <> 'credit_note' or original_invoice_id is not null),
  foreign key (tenant_id, account_id) references accounts (tenant_id, id) on delete set null (account_id),
  foreign key (tenant_id, contact_id) references contacts (tenant_id, id) on delete set null (contact_id),
  foreign key (tenant_id, sales_order_id) references sales_orders (tenant_id, id) on delete set null (sales_order_id),
  foreign key (tenant_id, milestone_id) references order_milestones (tenant_id, id) on delete set null (milestone_id),
  foreign key (tenant_id, original_invoice_id) references invoices (tenant_id, id) on delete restrict,
  foreign key (tenant_id, owner_id) references users (tenant_id, id) on delete set null (owner_id)
);
-- the GST series is unique per document type
create unique index invoices_number on invoices (tenant_id, doc_type, invoice_number) where invoice_number is not null;
create index invoices_account on invoices (tenant_id, account_id, invoice_date) where deleted_at is null;
create index invoices_order on invoices (tenant_id, sales_order_id) where deleted_at is null;
create index invoices_period on invoices (tenant_id, invoice_date) where status <> 'draft' and deleted_at is null;
create index invoices_due on invoices (due_date) where status in ('issued', 'partially_paid') and overdue_notified_at is null and deleted_at is null;
create index invoices_name_trgm on invoices using gin (name gin_trgm_ops);

create table invoice_lines (
  id             uuid primary key default app.uuidv7(),
  tenant_id      uuid not null default app.current_tenant_id() references tenants (id) on delete cascade,
  order_id       uuid not null,  -- the invoice (name shared with the other line tables)
  position       integer not null default 0,
  product_id     uuid,
  order_line_id  uuid,
  name           text not null,
  description    text,
  hsn_sac        text,
  unit           text,
  is_service     boolean not null default false,
  quantity       numeric(14, 3) not null default 1 check (quantity > 0),
  unit_price     numeric(18, 2) not null default 0 check (unit_price >= 0),
  discount_pct   numeric(5, 2) not null default 0 check (discount_pct between 0 and 100),
  tax_rate       numeric(5, 2) not null default 0 check (tax_rate between 0 and 100),
  line_subtotal  numeric(18, 2) not null default 0,
  line_tax       numeric(18, 2) not null default 0,
  line_total     numeric(18, 2) not null default 0,
  line_cgst      numeric(18, 2) not null default 0,
  line_sgst      numeric(18, 2) not null default 0,
  line_igst      numeric(18, 2) not null default 0,
  unique (tenant_id, id),
  foreign key (tenant_id, order_id) references invoices (tenant_id, id) on delete cascade,
  foreign key (tenant_id, product_id) references products (tenant_id, id) on delete set null (product_id),
  foreign key (tenant_id, order_line_id) references sales_order_lines (tenant_id, id) on delete set null (order_line_id)
);
create index invoice_lines_invoice on invoice_lines (tenant_id, order_id, position);

alter table order_milestones add foreign key (tenant_id, invoice_id) references invoices (tenant_id, id) on delete set null (invoice_id);

create table payments (
  id                 uuid primary key default app.uuidv7(),
  tenant_id          uuid not null default app.current_tenant_id() references tenants (id) on delete cascade,
  name               text not null,
  payment_number     text,
  status             text not null default 'received' check (status in ('received', 'void')),
  account_id         uuid,
  sales_order_id     uuid,
  milestone_id       uuid,
  payment_date       date not null default current_date,
  amount             numeric(18, 2) not null check (amount > 0),
  amount_allocated   numeric(18, 2) not null default 0,
  unallocated        numeric(18, 2) generated always as (amount - amount_allocated) stored,
  mode               text not null default 'bank_transfer' check (mode in ('cash', 'upi', 'bank_transfer', 'cheque', 'card', 'other')),
  reference          text check (length(reference) <= 120),
  financial_year     text,
  notes              text,
  void_reason        text,
  owner_id           uuid,
  custom             jsonb not null default '{}'::jsonb,
  created_by         uuid default app.current_user_id(),
  updated_by         uuid,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  deleted_at         timestamptz,
  merged_into        uuid,
  version            integer not null default 1,
  unique (tenant_id, id),
  check (amount_allocated >= 0 and amount_allocated <= amount),
  foreign key (tenant_id, account_id) references accounts (tenant_id, id) on delete set null (account_id),
  foreign key (tenant_id, sales_order_id) references sales_orders (tenant_id, id) on delete set null (sales_order_id),
  foreign key (tenant_id, milestone_id) references order_milestones (tenant_id, id) on delete set null (milestone_id),
  foreign key (tenant_id, owner_id) references users (tenant_id, id) on delete set null (owner_id)
);
create unique index payments_number on payments (tenant_id, payment_number) where payment_number is not null;
create index payments_account on payments (tenant_id, account_id, payment_date) where deleted_at is null;
create index payments_order on payments (tenant_id, sales_order_id) where deleted_at is null;
create index payments_name_trgm on payments using gin (name gin_trgm_ops);

create table payment_allocations (
  tenant_id   uuid not null default app.current_tenant_id() references tenants (id) on delete cascade,
  payment_id  uuid not null,
  invoice_id  uuid not null,
  amount      numeric(18, 2) not null check (amount > 0),
  created_at  timestamptz not null default now(),
  primary key (tenant_id, payment_id, invoice_id),
  foreign key (tenant_id, payment_id) references payments (tenant_id, id) on delete cascade,
  foreign key (tenant_id, invoice_id) references invoices (tenant_id, id) on delete cascade
);
create index payment_allocations_invoice on payment_allocations (tenant_id, invoice_id);

-- ---------------------------------------------------------------------------------------------
-- RLS, grants, triggers
-- ---------------------------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['invoices', 'invoice_lines', 'payments', 'payment_allocations'] loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
    execute format($p$create policy tenant_isolation on %I as permissive for all to public
      using (tenant_id = (select app.current_tenant_id()))
      with check (tenant_id = (select app.current_tenant_id()))$p$, t);
    execute format('grant select, insert, update, delete on %I to synapse_app', t);
  end loop;
end
$$;

-- an issued GST document is immutable except for its payment state, e-invoice details and cancellation
create or replace function app.guard_issued_invoice() returns trigger
language plpgsql as $$
begin
  if old.status <> 'draft' and old.invoice_number is not null then
    if (to_jsonb(new) - array['status', 'amount_paid', 'amount_credited', 'balance_due', 'irn', 'ack_no', 'ack_date', 'cancelled_at', 'cancel_reason',
                              'overdue_notified_at', 'updated_at', 'updated_by', 'version', 'custom', 'owner_id', 'notes', 'approval_status', 'deleted_at'])
       is distinct from
       (to_jsonb(old) - array['status', 'amount_paid', 'amount_credited', 'balance_due', 'irn', 'ack_no', 'ack_date', 'cancelled_at', 'cancel_reason',
                              'overdue_notified_at', 'updated_at', 'updated_by', 'version', 'custom', 'owner_id', 'notes', 'approval_status', 'deleted_at']) then
      raise exception 'issued invoice % cannot be changed', old.invoice_number using errcode = 'check_violation';
    end if;
  end if;
  return new;
end
$$;
create trigger invoices_guard before update on invoices for each row execute function app.guard_issued_invoice();

create or replace function app.guard_issued_invoice_lines() returns trigger
language plpgsql as $$
declare
  inv uuid := coalesce(new.order_id, old.order_id);
  t uuid := coalesce(new.tenant_id, old.tenant_id);
begin
  if exists (select 1 from invoices where tenant_id = t and id = inv and status <> 'draft' and invoice_number is not null) then
    raise exception 'lines of an issued invoice cannot be changed' using errcode = 'check_violation';
  end if;
  return coalesce(new, old);
end
$$;
create trigger invoice_lines_guard before insert or update or delete on invoice_lines for each row execute function app.guard_issued_invoice_lines();

create trigger invoices_touch before update on invoices for each row execute function app.touch_row();
create trigger payments_touch before update on payments for each row execute function app.touch_row();

create trigger invoices_rindex after insert or update or delete on invoices for each row execute function app.sync_record_index('invoice');
create trigger payments_rindex after insert or update or delete on payments for each row execute function app.sync_record_index('payment');

create trigger invoices_audit            after insert or update or delete on invoices            for each row execute function app.audit_row_change('invoice');
create trigger payments_audit            after insert or update or delete on payments            for each row execute function app.audit_row_change('payment');
create trigger payment_allocations_audit after insert or update or delete on payment_allocations for each row execute function app.audit_row_change('payment_allocation');
